import{_ as e,o as a,c as s,a0 as n}from"./chunks/framework.CI7OaYtj.js";const g=JSON.parse('{"title":"路由篇","description":"","frontmatter":{},"headers":[],"relativePath":"guide/route.md","filePath":"guide/route.md"}'),l={name:"guide/route.md"};function d(p,t,o,i,c,r){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="路由篇" tabindex="-1">路由篇 <a class="header-anchor" href="#路由篇" aria-label="Permalink to &quot;路由篇&quot;">​</a></h1><p>项目路由基于 <a href="https://github.com/cq112233/unibestX/tree/main/uni_modules/route-bestX" target="_blank" rel="noreferrer"><code>route-bestX</code></a> 开发，<code>src/router</code> 负责业务层组装：初始化全局单例、注册登录与维护守卫、桥接 TabBar、加载构建期路由表。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>页面 / 组件</span></span>
<span class="line"><span>    ↓ useRouter()</span></span>
<span class="line"><span>src/router</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>route-bestX</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>uni.navigateTo / redirectTo / reLaunch / navigateBack</span></span></code></pre></div><blockquote><p>业务页面禁止直接调用 <code>uni.navigateTo</code>、<code>uni.redirectTo</code>、<code>uni.reLaunch</code>、<code>uni.switchTab</code>、<code>uni.navigateBack</code>。直接调用会绕过登录拦截、维护守卫、TabBar 分流与路由状态同步。</p></blockquote><h2 id="分层与导入" tabindex="-1">分层与导入 <a class="header-anchor" href="#分层与导入" aria-label="Permalink to &quot;分层与导入&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">能力</th><th style="text-align:left;">位置</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">路由引擎</td><td style="text-align:left;"><code>uni_modules/route-bestX/</code></td><td style="text-align:left;">跳转、快照、守卫、错误码、URL 工具</td></tr><tr><td style="text-align:left;">业务路由层</td><td style="text-align:left;"><code>src/router/index.uts</code></td><td style="text-align:left;">创建 <code>router</code> 单例、安装业务守卫</td></tr><tr><td style="text-align:left;">守卫规则</td><td style="text-align:left;"><code>src/router/guards/</code></td><td style="text-align:left;">维护守卫与登录守卫责任链</td></tr><tr><td style="text-align:left;">业务配置</td><td style="text-align:left;"><code>src/router/config.uts</code></td><td style="text-align:left;">登录页、首页、黑白名单策略</td></tr><tr><td style="text-align:left;">页面路由表</td><td style="text-align:left;"><code>virtual:uni-pages-route-table</code></td><td style="text-align:left;">构建期生成，不落盘</td></tr></tbody></table><p>页面统一从业务门面导入：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { useRoute, useRouter } from &#39;@/src/router/index.uts&#39;;</span></span></code></pre></div><p>需要路径工具时从模块入口导入：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import {</span></span>
<span class="line"><span>  getCurrentPath,</span></span>
<span class="line"><span>  getCurrentRoute,</span></span>
<span class="line"><span>  isSamePath</span></span>
<span class="line"><span>} from &#39;@/uni_modules/route-bestX/index.uts&#39;;</span></span></code></pre></div><p>不要导入 <code>route-bestX</code> 的 <code>core/</code>、<code>hooks/</code>、<code>interceptor/</code> 等内部文件。</p><h2 id="读取当前路由" tabindex="-1">读取当前路由 <a class="header-anchor" href="#读取当前路由" aria-label="Permalink to &quot;读取当前路由&quot;">​</a></h2><p><code>useRoute()</code> 返回当前页面专属的响应式只读快照。只能在页面或组件的 <code>setup</code> 中调用，每次调用都是一份独立快照。</p><table tabindex="0"><thead><tr><th style="text-align:left;">字段</th><th style="text-align:left;">类型</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>path</code></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">规范化路径，带前导 <code>/</code>，不含 query</td></tr><tr><td style="text-align:left;"><code>fullPath</code></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">路径与编码后的 query 串</td></tr><tr><td style="text-align:left;"><code>query</code></td><td style="text-align:left;"><code>Map&lt;string, string&gt;</code></td><td style="text-align:left;">已解码的查询参数，使用 <code>.get()</code> 读取</td></tr><tr><td style="text-align:left;"><code>params</code></td><td style="text-align:left;"><code>Map&lt;string, string&gt;</code></td><td style="text-align:left;">恒为空；命名路由的 params 会转成 query</td></tr><tr><td style="text-align:left;"><code>meta</code></td><td style="text-align:left;"><code>UTSJSONObject | null</code></td><td style="text-align:left;">来自 <code>definePage</code> / <code>pages.json</code> 的页面元数据</td></tr><tr><td style="text-align:left;"><code>name</code></td><td style="text-align:left;"><code>string | null</code></td><td style="text-align:left;">路由名，未声明时回落到路径最后一段</td></tr><tr><td style="text-align:left;"><code>page</code></td><td style="text-align:left;"><code>any | null</code></td><td style="text-align:left;">当前栈顶页面实例</td></tr><tr><td style="text-align:left;"><code>pages</code></td><td style="text-align:left;"><code>UniPage[]</code></td><td style="text-align:left;">当前页面栈快照</td></tr></tbody></table><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { computed } from &#39;vue&#39;;</span></span>
<span class="line"><span>import { useRoute } from &#39;@/src/router/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>definePage({</span></span>
<span class="line"><span>  name: &#39;detail&#39;,</span></span>
<span class="line"><span>  layout: &#39;navbar&#39;,</span></span>
<span class="line"><span>  showBack: true,</span></span>
<span class="line"><span>  style: {</span></span>
<span class="line"><span>    navigationBarTitleText: &#39;详情页&#39;,</span></span>
<span class="line"><span>    navigationStyle: &#39;custom&#39;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const route = useRoute();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type DetailQuery = {</span></span>
<span class="line"><span>  id: number;</span></span>
<span class="line"><span>  title: string;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const detailQuery = computed((): DetailQuery =&gt; {</span></span>
<span class="line"><span>  const idText = route.query.get(&#39;id&#39;);</span></span>
<span class="line"><span>  let id: number = 0;</span></span>
<span class="line"><span>  if (idText != null) {</span></span>
<span class="line"><span>    id = parseInt(idText, 10);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  return {</span></span>
<span class="line"><span>    id: id,</span></span>
<span class="line"><span>    title: route.query.get(&#39;title&#39;) ?? &#39;&#39;</span></span>
<span class="line"><span>  } as DetailQuery;</span></span>
<span class="line"><span>});</span></span></code></pre></div><h3 id="参数规则" tabindex="-1">参数规则 <a class="header-anchor" href="#参数规则" aria-label="Permalink to &quot;参数规则&quot;">​</a></h3><ul><li><code>query</code> 的值永远是 <code>string</code>，数字与布尔值必须显式转换。</li><li><code>route.params</code> 恒为空，命名路由参数也会进入 <code>query</code>。</li><li><code>fullPath</code> 中的 query 是编码态；展示中文时读取 <code>query.get()</code>。</li><li>不要解构 <code>useRoute()</code>，否则会丢失响应式与快照语义。</li><li>不要用 <code>onLoad(options)</code> 或 <code>getCurrentPages()</code> 取代 <code>useRoute()</code>。</li></ul><h3 id="读取页面-meta" tabindex="-1">读取页面 meta <a class="header-anchor" href="#读取页面-meta" aria-label="Permalink to &quot;读取页面 meta&quot;">​</a></h3><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const meta = route.meta;</span></span>
<span class="line"><span>let pageTitle: string = &#39;详情页&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if (meta != null) {</span></span>
<span class="line"><span>  const style = meta[&#39;style&#39;];</span></span>
<span class="line"><span>  if (style != null) {</span></span>
<span class="line"><span>    const styleObj = style as UTSJSONObject;</span></span>
<span class="line"><span>    const title = styleObj[&#39;navigationBarTitleText&#39;];</span></span>
<span class="line"><span>    if (title != null) {</span></span>
<span class="line"><span>      pageTitle = \`\${title}\`;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>meta</code> 和嵌套的 <code>style</code> 都可能为 <code>null</code>，必须逐层判空后使用下标访问。</p><h2 id="页面跳转" tabindex="-1">页面跳转 <a class="header-anchor" href="#页面跳转" aria-label="Permalink to &quot;页面跳转&quot;">​</a></h2><p><code>useRouter()</code> 返回全局唯一导航器。推荐使用对象形态，由路由层自动序列化和编码 query。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方法</th><th style="text-align:left;">用途</th><th style="text-align:left;">底层行为</th></tr></thead><tbody><tr><td style="text-align:left;"><code>router.push(to)</code></td><td style="text-align:left;">打开新页面，保留当前页</td><td style="text-align:left;"><code>uni.navigateTo</code>，Tab 页自动分流</td></tr><tr><td style="text-align:left;"><code>router.replace(to)</code></td><td style="text-align:left;">替换当前页面</td><td style="text-align:left;"><code>uni.redirectTo</code>，Tab 页自动分流</td></tr><tr><td style="text-align:left;"><code>router.relaunch(to)</code></td><td style="text-align:left;">关闭全部页面并打开目标页</td><td style="text-align:left;"><code>uni.reLaunch</code></td></tr><tr><td style="text-align:left;"><code>router.switchTab(to)</code></td><td style="text-align:left;">切换 Tab 页面</td><td style="text-align:left;">转发到 <code>switchTabbar()</code></td></tr><tr><td style="text-align:left;"><code>router.back(delta?)</code></td><td style="text-align:left;">返回上一页或前 N 页</td><td style="text-align:left;"><code>uni.navigateBack</code></td></tr><tr><td style="text-align:left;"><code>router.go(delta)</code></td><td style="text-align:left;">按步长后退，只支持负数</td><td style="text-align:left;"><code>uni.navigateBack</code></td></tr><tr><td style="text-align:left;"><code>router.resolve(to)</code></td><td style="text-align:left;">只解析目标 URL，不跳转</td><td style="text-align:left;">返回完整 URL 字符串</td></tr></tbody></table><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { useRouter } from &#39;@/src/router/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const router = useRouter();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 普通路径跳转 */</span></span>
<span class="line"><span>function openDetail(): void {</span></span>
<span class="line"><span>  router.push({</span></span>
<span class="line"><span>    path: &#39;/src/sub/detail/detail&#39;,</span></span>
<span class="line"><span>    query: { id: 1001, title: &#39;详情页&#39; }</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 命名路由跳转 */</span></span>
<span class="line"><span>function openByName(): void {</span></span>
<span class="line"><span>  router.push({</span></span>
<span class="line"><span>    name: &#39;detail&#39;,</span></span>
<span class="line"><span>    params: { id: 1002, from: &#39;name-route&#39; }</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 登录成功后替换当前页 */</span></span>
<span class="line"><span>function replaceToHome(): void {</span></span>
<span class="line"><span>  router.replace(&#39;/src/pages/index/index&#39;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 返回上一页 */</span></span>
<span class="line"><span>function back(): void {</span></span>
<span class="line"><span>  router.back();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>切换 TabBar 时可以统一使用 <code>router.push()</code>，也可明确调用 <code>switchTabbar()</code>：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { switchTabbar } from &#39;@/src/tabbar/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>router.push(&#39;/src/pages/me/me&#39;);</span></span>
<span class="line"><span>switchTabbar(&#39;/src/pages/me/me&#39;);</span></span></code></pre></div><p>不要直接调用 <code>uni.switchTab</code>，否则会绕过自定义 TabBar 的选中态、保活与路由同步。</p><h2 id="全局守卫" tabindex="-1">全局守卫 <a class="header-anchor" href="#全局守卫" aria-label="Permalink to &quot;全局守卫&quot;">​</a></h2><p>业务守卫集中在 <code>src/router/guards/</code>，按固定顺序执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>guardMaintenance（停服维护）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>guardLogin（登录鉴权）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>next() 放行</span></span></code></pre></div><p>任一规则不通过都会立即短路，后续规则不再执行。<code>next()</code> 的裁决方式与 Vue Router 一致：</p><table tabindex="0"><thead><tr><th style="text-align:left;">调用</th><th style="text-align:left;">结果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>next()</code></td><td style="text-align:left;">放行</td></tr><tr><td style="text-align:left;"><code>next(false)</code></td><td style="text-align:left;">取消本次导航</td></tr><tr><td style="text-align:left;"><code>next(&#39;/src/sub/auth/login&#39;)</code></td><td style="text-align:left;">改跳目标页</td></tr><tr><td style="text-align:left;"><code>next({ path, query, replace: true })</code></td><td style="text-align:left;">改跳并替换当前页</td></tr></tbody></table><h3 id="登录策略" tabindex="-1">登录策略 <a class="header-anchor" href="#登录策略" aria-label="Permalink to &quot;登录策略&quot;">​</a></h3><p><code>src/router/config.uts</code> 维护登录页、首页与黑白名单：</p><table tabindex="0"><thead><tr><th style="text-align:left;">配置</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>LOGIN_PAGE</code></td><td style="text-align:left;">登录页路径</td></tr><tr><td style="text-align:left;"><code>REGISTER_PAGE</code></td><td style="text-align:left;">注册页路径</td></tr><tr><td style="text-align:left;"><code>DEFAULT_HOME_PAGE</code></td><td style="text-align:left;">登录成功后的默认回跳页</td></tr><tr><td style="text-align:left;"><code>LOGIN_STRATEGY</code></td><td style="text-align:left;">黑名单 / 白名单策略</td></tr><tr><td style="text-align:left;"><code>EXCLUDE_LOGIN_PATH_LIST</code></td><td style="text-align:left;">策略页面名单</td></tr></tbody></table><p>未登录访问受保护页面时，守卫会带上 <code>redirect</code>：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const loginUrl = \`\${LOGIN_PAGE}?redirect=\${encodeURIComponent(to.fullPath)}\`;</span></span>
<span class="line"><span>return next(loginUrl);</span></span></code></pre></div><p>登录页读取并回跳：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { DEFAULT_HOME_PAGE } from &#39;@/src/router/config.uts&#39;;</span></span>
<span class="line"><span>import { useRoute, useRouter } from &#39;@/src/router/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const route = useRoute();</span></span>
<span class="line"><span>const router = useRouter();</span></span>
<span class="line"><span>const redirect = route.query.get(&#39;redirect&#39;) ?? &#39;&#39;;</span></span>
<span class="line"><span>const target = redirect != &#39;&#39; ? redirect : DEFAULT_HOME_PAGE;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>router.replace(target);</span></span></code></pre></div><h3 id="新增业务守卫" tabindex="-1">新增业务守卫 <a class="header-anchor" href="#新增业务守卫" aria-label="Permalink to &quot;新增业务守卫&quot;">​</a></h3><ol><li>在 <code>src/router/guards/</code> 新建 <code>guardXxx.uts</code>，导出接收 <code>RouteGuardContext</code> 的纯函数。</li><li>在 <code>src/router/guards/index.uts</code> 中按优先级接入责任链。</li><li>需要中断或改跳时返回对应决策，全部通过后由流水线统一 <code>next()</code>。</li><li>不要在页面 <code>setup</code> 中重复注册 <code>beforeEach</code>。</li></ol><h2 id="tabbar-模式-4-的路由守卫" tabindex="-1">TabBar 模式 4 的路由守卫 <a class="header-anchor" href="#tabbar-模式-4-的路由守卫" aria-label="Permalink to &quot;TabBar 模式 4 的路由守卫&quot;">​</a></h2><p>模式 4 的 Tab 切换发生在宿主页内部，不调用 <code>uni.switchTab</code>，因此不会触发 route-bestX 的全局 <code>beforeEach</code> / <code>afterEach</code>。需要在虚拟 Tab 切换前处理第三方接入、参数换取、埋点或预取时，使用 Tab 级导航守卫：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import type {</span></span>
<span class="line"><span>  TabNavigationContext,</span></span>
<span class="line"><span>  TabNavigationNext</span></span>
<span class="line"><span>} from &#39;@/src/tabbar/index.uts&#39;;</span></span>
<span class="line"><span>import { registerTabNavigationGuard } from &#39;@/src/tabbar/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>registerTabNavigationGuard((context: TabNavigationContext, next: TabNavigationNext): void =&gt; {</span></span>
<span class="line"><span>  if (context.api == &#39;hostQuery&#39; &amp;&amp; context.query.get(&#39;from&#39;) == &#39;third-party&#39;) {</span></span>
<span class="line"><span>    // exchangeThirdPartySession 为业务自定义函数</span></span>
<span class="line"><span>    exchangeThirdPartySession(context.query).then((_res: any): void =&gt; {</span></span>
<span class="line"><span>      next(true);</span></span>
<span class="line"><span>    }, (_err: any): void =&gt; {</span></span>
<span class="line"><span>      next(false);</span></span>
<span class="line"><span>    });</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  next(true);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>上下文字段：</p><table tabindex="0"><thead><tr><th style="text-align:left;">字段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>from</code> / <code>fromPath</code></td><td style="text-align:left;">来源虚拟 Tab 的完整 URL / path</td></tr><tr><td style="text-align:left;"><code>to</code> / <code>toPath</code></td><td style="text-align:left;">目标虚拟 Tab 的完整 URL / path</td></tr><tr><td style="text-align:left;"><code>query</code></td><td style="text-align:left;">目标 query，值已解码</td></tr><tr><td style="text-align:left;"><code>api</code></td><td style="text-align:left;"><code>tabClick</code> / <code>router</code> / <code>hostQuery</code> / <code>switchTabbar</code></td></tr></tbody></table><p>必须调用一次 <code>next(true)</code> 或 <code>next(false)</code>。<code>next(true)</code> 后才写入激活索引、虚拟 query 与 H5 地址栏。Tab 到普通页面（例如“我的 → 登录”）仍会走全局守卫。</p><h2 id="直链与冷启动" tabindex="-1">直链与冷启动 <a class="header-anchor" href="#直链与冷启动" aria-label="Permalink to &quot;直链与冷启动&quot;">​</a></h2><p>项目已经在 <code>App.uvue</code> 中调用 <code>checkDirectEntry(options)</code>。App 冷启动、H5 刷新、分享链接和外部 Scheme 进入时，会自动同步页面栈并触发守卫，不需要页面额外处理。</p><h2 id="非组件环境读取路由" tabindex="-1">非组件环境读取路由 <a class="header-anchor" href="#非组件环境读取路由" aria-label="Permalink to &quot;非组件环境读取路由&quot;">​</a></h2><p>API 层、工具函数或守卫中不能调用 <code>useRoute()</code>，使用路由工具：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import {</span></span>
<span class="line"><span>  getCurrentPath,</span></span>
<span class="line"><span>  getCurrentRoute,</span></span>
<span class="line"><span>  isSamePath</span></span>
<span class="line"><span>} from &#39;@/uni_modules/route-bestX/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const path = getCurrentPath();</span></span>
<span class="line"><span>const rawRoute = getCurrentRoute();</span></span>
<span class="line"><span>const isMePage = isSamePath(path, &#39;/src/pages/me/me&#39;);</span></span></code></pre></div><p><code>router.currentRoute</code> / <code>routeState</code> 表示“当前或正在导航到的路由”，跳转发起后就会变化，禁止用于页面展示。</p><h2 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h2><p>导航失败统一交给全局 <code>afterEach</code> / <code>onError</code>，不要在 <code>router.push()</code> 后链式写 <code>.catch()</code>。</p><table tabindex="0"><thead><tr><th style="text-align:center;">错误码</th><th style="text-align:left;">常量</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:center;"><code>101</code></td><td style="text-align:left;"><code>GUARD_CANCELLED</code></td><td style="text-align:left;">守卫主动取消</td></tr><tr><td style="text-align:center;"><code>102</code></td><td style="text-align:left;"><code>MAX_REDIRECT_EXCEEDED</code></td><td style="text-align:left;">重定向超过上限</td></tr><tr><td style="text-align:center;"><code>201</code></td><td style="text-align:left;"><code>BACK_STACK_DEPTH_INVALID</code></td><td style="text-align:left;">页面栈深度不足</td></tr><tr><td style="text-align:center;"><code>202</code></td><td style="text-align:left;"><code>NAVIGATE_BACK_FAILED</code></td><td style="text-align:left;">返回失败</td></tr><tr><td style="text-align:center;"><code>301</code></td><td style="text-align:left;"><code>NAVIGATE_TO_FAILED</code></td><td style="text-align:left;">页面未注册或页面栈超限</td></tr><tr><td style="text-align:center;"><code>302</code></td><td style="text-align:left;"><code>REDIRECT_TO_FAILED</code></td><td style="text-align:left;"><code>redirectTo</code> 失败</td></tr><tr><td style="text-align:center;"><code>303</code></td><td style="text-align:left;"><code>RELAUNCH_FAILED</code></td><td style="text-align:left;"><code>reLaunch</code> 失败</td></tr><tr><td style="text-align:center;"><code>304</code></td><td style="text-align:left;"><code>SWITCH_TAB_FAILED</code></td><td style="text-align:left;">Tab 切换失败</td></tr></tbody></table><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import router from &#39;@/src/router/index.uts&#39;;</span></span>
<span class="line"><span>import { ROUTER_ERROR_CODE } from &#39;@/uni_modules/route-bestX/index.uts&#39;;</span></span>
<span class="line"><span>import type { RouteTarget } from &#39;@/uni_modules/route-bestX/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>router.afterEach((_to: RouteTarget, _from: RouteTarget, failure?: any | null): void =&gt; {</span></span>
<span class="line"><span>  if (failure != null &amp;&amp; failure.code == ROUTER_ERROR_CODE.GUARD_CANCELLED) {</span></span>
<span class="line"><span>    console.log(&#39;本次导航被守卫取消&#39;);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="常见场景" tabindex="-1">常见场景 <a class="header-anchor" href="#常见场景" aria-label="Permalink to &quot;常见场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">写法</th></tr></thead><tbody><tr><td style="text-align:left;">打开详情页</td><td style="text-align:left;"><code>router.push({ path, query })</code></td></tr><tr><td style="text-align:left;">命名路由</td><td style="text-align:left;"><code>router.push({ name, params })</code></td></tr><tr><td style="text-align:left;">登录成功回跳</td><td style="text-align:left;"><code>router.replace(target)</code></td></tr><tr><td style="text-align:left;">退出登录回首页</td><td style="text-align:left;"><code>router.relaunch(&#39;/src/pages/index/index&#39;)</code></td></tr><tr><td style="text-align:left;">切换 Tab</td><td style="text-align:left;"><code>router.push(tabPath)</code> / <code>switchTabbar(tabPath)</code></td></tr><tr><td style="text-align:left;">读取 query</td><td style="text-align:left;"><code>route.query.get(&#39;id&#39;)</code> 后显式转型</td></tr><tr><td style="text-align:left;">判断当前页</td><td style="text-align:left;"><code>isSamePath(route.path, &#39;/src/pages/me/me&#39;)</code></td></tr><tr><td style="text-align:left;">新增登录保护页</td><td style="text-align:left;">修改 <code>src/router/config.uts</code> 的策略名单</td></tr></tbody></table><h2 id="约束清单" tabindex="-1">约束清单 <a class="header-anchor" href="#约束清单" aria-label="Permalink to &quot;约束清单&quot;">​</a></h2><ul><li>页面导入只使用 <code>@/src/router/index.uts</code> 或 <code>@/uni_modules/route-bestX/index.uts</code>。</li><li>所有跳转统一走 <code>useRouter()</code> / <code>switchTabbar()</code>。</li><li>路由信息统一走 <code>useRoute()</code>，禁止 <code>onLoad</code> 取参和手写 <code>getCurrentPages()</code>。</li><li>query 值先判空再转型，缺失值必须有默认值。</li><li><code>meta</code> 及嵌套对象逐层判空。</li><li>业务守卫只在 <code>src/router/guards/index.uts</code> 编排。</li><li>模式 4 Tab 切换使用 Tab 级守卫，不要桥接回全局路由。</li></ul><blockquote><p>更完整的底层 API 见 <a href="https://github.com/cq112233/unibestX/tree/main/uni_modules/route-bestX" target="_blank" rel="noreferrer"><code>route-bestX</code> 文档</a> 与 <a href="https://github.com/cq112233/unibestX/blob/main/src/router/README.md" target="_blank" rel="noreferrer"><code>src/router/README.md</code></a>。</p></blockquote>`,62)])])}const h=e(l,[["render",d]]);export{g as __pageData,h as default};
